1	import 'dart:async';
2	
3	import 'package:flutter_bloc/flutter_bloc.dart';
4	import 'package:fpdart/fpdart.dart';
5	
6	import '../../../../core/failure/failure.dart';
7	import '../../domain/entities/chat_message.dart';
8	import '../../domain/entities/chat_session.dart';
9	import '../../domain/entities/chat_stream_event.dart';
10	import '../../domain/repositories/chat_repository.dart';
11	import '../../domain/services/connectivity_watcher.dart';
12	import 'chat_state.dart';
13	
14	/// Drives `ChatScreen` — a DI `lazySingleton` (Code Map, mirroring
15	/// `MeusRegistrosCubit`): long-lived, so returning to Home/Chat within the
16	/// same app session never re-bootstraps the session/history it already
17	/// loaded (`init()`'s own no-op guard below).
18	class ChatCubit extends Cubit<ChatState> {
19	  ChatCubit(this._repository, this._connectivityWatcher)
20	    : super(const ChatBootstrapLoading()) {
21	    // spec-6-3 — subscribes immediately (not gated on bootstrap), so the
22	    // very first connectivity read is never missed while a slow
23	    // `init()` is still in flight; `_handleConnectivityChange` itself is
24	    // a no-op against anything but `ChatReady` until bootstrap resolves,
25	    // `_isOffline` still being tracked below so a later `ChatReady`
26	    // (bootstrap, `switchSession`, `startNewSession`) picks up whatever
27	    // the device's status already was.
28	    _connectivitySubscription = _connectivityWatcher.watch().listen(
29	      _handleConnectivityChange,
30	      onError: (Object _, StackTrace _) {
31	        // RNF09: a connectivity-watch error (e.g. the platform channel
32	        // being unavailable — no device/simulator exists yet, AGENTS.md)
33	        // must never escape the cubit; `_isOffline` simply keeps
34	        // whatever value it last had (`false` if this is the very first
35	        // read) instead of crashing.
36	      },
37	    );
38	  }
39	
40	  final ChatRepository _repository;
41	  final ConnectivityWatcher _connectivityWatcher;
42	
43	  StreamSubscription<bool>? _connectivitySubscription;
44	
45	  StreamSubscription<Either<Failure, ChatStreamEvent>>? _sendSubscription;
46	
47	  /// The in-flight [sendMessage]/[retryMessage]'s own completer, if any —
48	  /// [close] must complete it itself, since cancelling [_sendSubscription]
49	  /// alone never fires `onDone`/`onError` (review fix: `cancel()` alone
50	  /// left `sendMessage()`'s returned `Future` permanently unresolved when
51	  /// the cubit closed mid-send).
52	  Completer<void>? _sendCompleter;
53	
54	  /// Monotonic counter behind every locally generated [ChatUiMessage.id]
55	  /// (Code Map) — never the server's own message id (see `ChatStreamEvent`'s
56	  /// own doc on why `message_created`'s id goes unused here).
57	  int _localIdCounter = 0;
58	
59	  /// Whether a send/retry is actively in flight right now — tracked
60	  /// locally rather than by scanning [ChatState.messages] for a persisted
61	  /// `streaming` status, since a message loaded from history/cache can
62	  /// legitimately carry that same status (e.g. one left over from an
63	  /// earlier dropped response, the I/O matrix's own scenario) without a
64	  /// send actually being in progress; scanning for it would permanently
65	  /// disable the composer in that case. [retryMessage] reuses this exact
66	  /// guard verbatim (Boundaries: "a second retry while one is in flight —
67	  /// reuses `_isSending` verbatim"), so a retry and a send can never race
68	  /// each other either.
69	  bool _isSending = false;
70	
71	  /// An in-flight bootstrap, if any — reused by a concurrent `init()` call
72	  /// instead of starting a second bootstrap, so two near-simultaneous
73	  /// callers (e.g. two mounts before the first resolves) never both
74	  /// observe "no sessions" and both call `createSession()` (Boundaries:
75	  /// "silently ensure *one* Chat Session exists").
76	  Future<void>? _initFuture;
77	
78	  /// spec-6-3 — the device's last known online/offline status, as
79	  /// reported by [_connectivityWatcher], `true` meaning offline. Tracked
80	  /// independently of [ChatState] (unlike `_isSending`'s own UI-facing
81	  /// twin, [ChatReady.isOffline]) so a status learned before bootstrap
82	  /// resolves — or while the active session is being switched, neither of
83	  /// which touches this field — is never lost; every place that emits a
84	  /// fresh [ChatReady] (`_bootstrap`, [switchSession], [startNewSession])
85	  /// carries it forward explicitly.
86	  bool _isOffline = false;
87	
88	  /// Boundaries: "Scroll-offset restore is in-memory only, keyed by
89	  /// `sessionId`, on `ChatCubit` (never Hive) — survives session switches
90	  /// within one app run, resets on restart." Lives on this long-lived
91	  /// `lazySingleton` cubit itself (Design Notes), never on [ChatReady] —
92	  /// a state value would otherwise have to be threaded through every
93	  /// unrelated `copyWith` call just to avoid losing it.
94	  final Map<String, double> _scrollOffsets = {};
95	
96	  /// Boundaries: "On opening Home/Chat, silently ensure one Chat Session
97	  /// exists (reuse the most recent from `chat-sessions-list`, else
98	  /// `chat-sessions-create` with no title)". A no-op once already
99	  /// [ChatReady] — `ChatScreen.initState()` calls this unconditionally on
100	  /// every mount, but a `lazySingleton` cubit may already be bootstrapped
101	  /// from an earlier visit.
102	  Future<void> init() {
103	    if (state is ChatReady || isClosed) {
104	      return Future.value();
105	    }
106	    return _initFuture ??= _bootstrap().whenComplete(() => _initFuture = null);
107	  }
108	
109	  Future<void> _bootstrap() async {
110	    emit(const ChatBootstrapLoading());
111	
112	    final sessionsResult = await _repository.listSessions();
113	    if (isClosed) {
114	      return;
115	    }
116	    // Captured by the closures below so the resulting [ChatReady] can
117	    // carry every known session (Code Map: "capture resolved sessions
118	    // into the emitted ChatReady"), not just the one picked to reuse.
119	    List<ChatSession> sessions = const [];
120	    final Either<Failure, ChatSession> sessionResult = await sessionsResult
121	        .match((failure) async => left(failure), (fetchedSessions) async {
122	          if (fetchedSessions.isEmpty) {
123	            final createResult = await _repository.createSession();
124	            return createResult.match((failure) => left(failure), (session) {
125	              sessions = [session];
126	              return right(session);
127	            });
128	          }
129	          sessions = fetchedSessions;
130	          // "reuse the most recent" — defensively re-sorts rather than
131	          // trusting `listSessions()`'s own ordering (its offline-cache
132	          // fallback already sorts `updatedAt` desc, but the live
133	          // server response's own ordering isn't documented either
134	          // way). `tryParse` (never `parse`) — same crash-safe pattern as
135	          // `AppDrawer`'s own session sort (review finding "Crash risk in
136	          // the new `_ConversasSection` sort"): a malformed `updatedAt`
137	          // must never crash bootstrap itself, so it falls back to the
138	          // epoch and simply sorts last instead of throwing.
139	          final mostRecent = [...fetchedSessions]..sort(
140	            (a, b) => (DateTime.tryParse(b.updatedAt) ?? DateTime(0))
141	                .compareTo(DateTime.tryParse(a.updatedAt) ?? DateTime(0)),
142	          );
143	          return right(mostRecent.first);
144	        });
145	    if (isClosed) {
146	      return;
147	    }
148	
149	    await sessionResult.match(
150	      (failure) async {
151	        if (!isClosed) {
152	          emit(ChatBootstrapError(failure));
153	        }
154	      },
155	      (session) async {
156	        final messagesResult = await _repository.listMessages(session.id);
157	        if (isClosed) {
158	          return;
159	        }
160	        messagesResult.match(
161	          (failure) => emit(ChatBootstrapError(failure)),
162	          (messages) => emit(
163	            ChatReady(
164	              sessionId: session.id,
165	              messages: messages.map(_fromDomain).toList(),
166	              sessions: sessions,
167	              isOffline: _isOffline,
168	            ),
169	          ),
170	        );
171	      },
172	    );
173	  }
174	
175	  /// Boundaries: "Scroll-offset restore is in-memory only, keyed by
176	  /// `sessionId`" — `ChatScreen`'s own `ScrollController` listener calls
177	  /// this on every scroll update, so whichever offset a session was last
178	  /// left at is always the one [switchSession] hands back when that
179	  /// session becomes active again.
180	  void recordScrollOffset(String sessionId, double offset) {
181	    _scrollOffsets[sessionId] = offset;
182	  }
183	
184	  /// I/O matrix: "Switch session"/"Switch to already-active session" —
185	  /// a no-op [Right] when [sessionId] is already [ChatReady.sessionId]
186	  /// (the drawer still closes, nothing reloads/re-fetches); otherwise
187	  /// fetches that session's own history via `listMessages` (reused as-is,
188	  /// Code Map) and makes it active, handing [ChatReady.restoreScrollOffset]
189	  /// whatever [recordScrollOffset] last captured for it (`null` if this
190	  /// session was never scrolled in this app run — `ChatScreen`'s own cue
191	  /// to jump to the bottom instead). A no-op while bootstrap hasn't
192	  /// resolved yet, same guard shape as [sendMessage].
193	  Future<Either<Failure, Unit>> switchSession(String sessionId) async {
194	    final current = state;
195	    if (current is! ChatReady) {
196	      return right(unit);
197	    }
198	    if (sessionId == current.sessionId) {
199	      return right(unit);
200	    }
201	    // Review finding: "Cross-session stream leakage" — an AI response
202	    // still streaming into the *old* session must never be left running
203	    // once we switch away from it; its orphaned subscription's
204	    // `onData`/`onDone` would otherwise go on to mutate whichever session
205	    // becomes active next.
206	    await _cancelInFlightSend();
207	    final messagesResult = await _repository.listMessages(sessionId);
208	    if (isClosed) {
209	      return right(unit);
210	    }
211	    return messagesResult.match(
212	      (failure) {
213	        // Review fix: `_cancelInFlightSend()` above only resets the
214	        // internal `_isSending` guard, not the `ChatReady.isSending` the
215	        // composer gates on (`canSend = ... && !state.isSending`) — on a
216	        // failed switch we're staying on `current`, so its stale
217	        // `isSending: true` must be flipped back here or the composer
218	        // would stay disabled for the rest of the app run.
219	        if (!isClosed && current.isSending) {
220	          emit(current.copyWith(isSending: false));
221	        }
222	        return left(failure);
223	      },
224	      (messages) {
225	        if (!isClosed) {
226	          emit(
227	            ChatReady(
228	              sessionId: sessionId,
229	              messages: messages.map(_fromDomain).toList(),
230	              sessions: current.sessions,
231	              restoreScrollOffset: _scrollOffsets[sessionId],
232	              isOffline: _isOffline,
233	            ),
234	          );
235	        }
236	        return right(unit);
237	      },
238	    );
239	  }
240	
241	  /// I/O matrix: "New session online"/"New session offline" — calls
242	  /// `createSession()` (reused as-is, Code Map; already blocked offline
243	  /// at the repository level, Boundaries). On any [Left] (including
244	  /// [Failure.networkOffline]), the current session is left completely
245	  /// untouched — no state is emitted at all, only the [Failure] is handed
246	  /// back for `AppDrawer` to surface as a transient `SnackBar`
247	  /// (Boundaries). On success, the new session opens empty and becomes
248	  /// active, prepended to [ChatReady.sessions].
249	  Future<Either<Failure, Unit>> startNewSession() async {
250	    final current = state;
251	    if (current is! ChatReady) {
252	      return right(unit);
253	    }
254	    // Review finding: "Cross-session stream leakage" — same rationale as
255	    // [switchSession]'s own cancellation above; a brand new session is
256	    // never the same session as [current], so this always needs to run
257	    // (unlike [switchSession], there's no same-session no-op branch to
258	    // skip it for).
259	    await _cancelInFlightSend();
260	    final result = await _repository.createSession();
261	    if (isClosed) {
262	      return right(unit);
263	    }
264	    return result.match(
265	      (failure) {
266	        // Review fix: same stuck-`isSending` risk as [switchSession] — a
267	        // failed `createSession()` leaves `current` active, so its stale
268	        // `isSending: true` (left behind by `_cancelInFlightSend()`
269	        // above, which never emits) must be flipped back here.
270	        if (!isClosed && current.isSending) {
271	          emit(current.copyWith(isSending: false));
272	        }
273	        return left(failure);
274	      },
275	      (session) {
276	        if (!isClosed) {
277	          emit(
278	            ChatReady(
279	              sessionId: session.id,
280	              messages: const [],
281	              sessions: [session, ...current.sessions],
282	              isOffline: _isOffline,
283	            ),
284	          );
285	        }
286	        return right(unit);
287	      },
288	    );
289	  }
290	
291	  ChatUiMessage _fromDomain(ChatMessage message) => ChatUiMessage(
292	    id: message.id,
293	    role: message.role,
294	    content: message.content,
295	    status: message.status,
296	    // spec-6-3 — every message reloaded from `chat-messages-list`/the
297	    // offline cache already has a persisted server id (unlike a message
298	    // created locally mid-session, which only gains one once/if
299	    // `message_created` arrives, Design Notes); [retryMessage] reads this
300	    // off the *user* message immediately preceding a `failed` AI bubble.
301	    serverId: message.id,
302	  );
303	
304	  /// Boundaries: optimistic user bubble, then subscribes to
305	  /// `ChatRepository.sendMessage`'s own stream, appending tokens as they
306	  /// arrive and finalizing/failing the AI bubble on `done`/any `Left` —
307	  /// the bubble's own [ChatUiMessage.content] is never cleared on failure
308	  /// (I/O matrix), only its [ChatUiMessage.status] changes.
309	  ///
310	  /// A no-op while [state] isn't [ChatReady] (bootstrap still in flight
311	  /// or failed — the composer is disabled in that case anyway), while
312	  /// [content] is blank once trimmed, while [_isSending] is already
313	  /// true — this story never races two concurrent sends against the one
314	  /// in-memory session — or while [ChatReady.isOffline] (review finding:
315	  /// the offline lock was UI-only via `_ChatComposer.canSend`, but nothing
316	  /// stopped a direct `sendMessage` caller from firing a real network call
317	  /// while the offline banner's own "novas mensagens bloqueadas" copy says
318	  /// otherwise). Deliberately not keyed off any loaded message's
319	  /// persisted `streaming` status — a message restored from history/cache
320	  /// can legitimately carry that status without a send actually being in
321	  /// flight (I/O matrix: mid-stream drop).
322	  Future<void> sendMessage(String content) async {
323	    final trimmed = content.trim();
324	    if (trimmed.isEmpty) {
325	      return;
326	    }
327	    final current = state;
328	    if (current is! ChatReady) {
329	      return;
330	    }
331	    if (_isSending || current.isOffline) {
332	      return;
333	    }
334	    _isSending = true;
335	
336	    final userMessage = ChatUiMessage(
337	      id: _nextLocalId(),
338	      role: ChatMessageRole.user,
339	      content: trimmed,
340	      status: ChatMessageStatus.complete,
341	    );
342	    final aiMessage = ChatUiMessage(
343	      id: _nextLocalId(),
344	      role: ChatMessageRole.assistant,
345	      content: '',
346	      status: ChatMessageStatus.streaming,
347	    );
348	    emit(
349	      current.copyWith(
350	        messages: [...current.messages, userMessage, aiMessage],
351	        isSending: true,
352	      ),
353	    );
354	
355	    await _consumeStream(
356	      _repository.sendMessage(current.sessionId, trimmed),
357	      userMessageId: userMessage.id,
358	      aiMessageId: aiMessage.id,
359	    );
360	  }
361	
362	  /// spec-6-3 — Boundaries: "Retry resets the *same* bubble (id,
363	  /// position) to `streaming`/empty, then reuses `_applyStreamEvent`/
364	  /// `_markFailed` unchanged — never a second bubble, never a duplicate
365	  /// question." [aiMessageId] must identify an existing `failed` AI
366	  /// bubble; anything else (not found, not `failed`, no preceding user
367	  /// message — shouldn't structurally happen) is a silent no-op, same
368	  /// defensive shape [sendMessage]'s own guards use.
369	  ///
370	  /// Keyed by the preceding user message's [ChatUiMessage.serverId]
371	  /// (Boundaries: "keyed by the user message's persisted id") — calls
372	  /// `ChatRepository.retryMessage` when it's known, or falls back to a
373	  /// full [ChatRepository.sendMessage] resend of that same user content
374	  /// into this exact AI bubble slot when it's `null` (I/O matrix: "Tap
375	  /// retry, no `serverId`" — the stream dropped before `message_created`
376	  /// ever arrived, so the backend never actually persisted the question;
377	  /// Boundaries: "Never calling `chat-messages-retry` with no `serverId`").
378	  /// Reuses [_isSending] verbatim (Boundaries: "A second retry while one
379	  /// is in flight"), so this is a no-op while a send/retry is already in
380	  /// flight — and, like [sendMessage] (review finding), a no-op while
381	  /// [ChatReady.isOffline] too: a failed bubble's retry tap is a separate
382	  /// affordance from the composer, not covered by `_ChatComposer.canSend`
383	  /// alone, so it needs this exact same guard to honor the offline banner.
384	  Future<void> retryMessage(String aiMessageId) async {
385	    final current = state;
386	    if (current is! ChatReady) {
387	      return;
388	    }
389	    if (_isSending || current.isOffline) {
390	      return;
391	    }
392	    final messages = current.messages;
393	    final aiIndex = messages.indexWhere((message) => message.id == aiMessageId);
394	    // Review finding: defensively checks `role` too, even though only an
395	    // assistant message ever reaches `failed` status today — matches this
396	    // guard clause's own already-defensive shape (`aiIndex == -1`, a
397	    // not-found/structurally-impossible case).
398	    if (aiIndex == -1 ||
399	        messages[aiIndex].role != ChatMessageRole.assistant ||
400	        messages[aiIndex].status != ChatMessageStatus.failed) {
401	      return;
402	    }
403	    ChatUiMessage? userMessage;
404	    for (var i = aiIndex - 1; i >= 0; i--) {
405	      if (messages[i].role == ChatMessageRole.user) {
406	        userMessage = messages[i];
407	        break;
408	      }
409	    }
410	    if (userMessage == null) {
411	      return;
412	    }
413	
414	    _isSending = true;
415	    emit(
416	      current.copyWith(
417	        messages: [
418	          for (final message in current.messages)
419	            if (message.id == aiMessageId)
420	              message.copyWith(content: '', status: ChatMessageStatus.streaming)
421	            else
422	              message,
423	        ],
424	        isSending: true,
425	      ),
426	    );
427	
428	    final serverId = userMessage.serverId;
429	    final stream = serverId == null
430	        ? _repository.sendMessage(current.sessionId, userMessage.content)
431	        : _repository.retryMessage(current.sessionId, serverId);
432	    await _consumeStream(
433	      stream,
434	      userMessageId: userMessage.id,
435	      aiMessageId: aiMessageId,
436	    );
437	  }
438	
439	  /// Shared by [sendMessage]/[retryMessage] (Code Map: "extract shared ...
440	  /// helper" extends to this subscribe-and-wait shape too, not just
441	  /// `ChatRemoteDataSource`'s own SSE buffering) — subscribes to [stream],
442	  /// routing every emission through [_applyStreamEvent]/[_markFailed], and
443	  /// resolves once the stream ends (`done`, an in-band error, or a
444	  /// stream-level error), clearing [_isSending]/[ChatReady.isSending]
445	  /// either way via [_finishSending].
446	  Future<void> _consumeStream(
447	    Stream<Either<Failure, ChatStreamEvent>> stream, {
448	    required String userMessageId,
449	    required String aiMessageId,
450	  }) async {
451	    await _sendSubscription?.cancel();
452	    final completer = Completer<void>();
453	    _sendCompleter = completer;
454	    _sendSubscription = stream.listen(
455	      (event) {
456	        event.match(
457	          (failure) => _markFailed(aiMessageId),
458	          (streamEvent) =>
459	              _applyStreamEvent(userMessageId, aiMessageId, streamEvent),
460	        );
461	      },
462	      onError: (Object _, StackTrace _) {
463	        // RNF09: no exception escapes the cubit — a stream-level error
464	        // (shouldn't happen, `ChatRemoteDataSource` never lets one through
465	        // unmapped) still only fails the bubble, never crashes.
466	        _markFailed(aiMessageId);
467	        _finishSending();
468	        if (!completer.isCompleted) {
469	          completer.complete();
470	        }
471	        // Review finding: a stale, already-done subscription reference
472	        // left on `_sendSubscription` made a *later* send/retry's own
473	        // `await _sendSubscription?.cancel()` above hang indefinitely in
474	        // practice (observed via a widget test driving two sends back to
475	        // back) — cleared here (and in the `onDone` branch below)
476	        // exactly where this stream's own lifecycle actually ends,
477	        // rather than relying on cancelling an already-finished
478	        // subscription being an instant no-op.
479	        _sendSubscription = null;
480	        _sendCompleter = null;
481	      },
482	      onDone: () {
483	        _finishSending();
484	        if (!completer.isCompleted) {
485	          completer.complete();
486	        }
487	        _sendSubscription = null;
488	        _sendCompleter = null;
489	      },
490	      cancelOnError: false,
491	    );
492	    await completer.future;
493	  }
494	
495	  /// Clears both the internal re-entrancy guard and the UI-facing
496	  /// [ChatReady.isSending] signal once a send's stream has ended (`done`,
497	  /// an in-band error, or a stream-level error) — the single place both
498	  /// flip back together.
499	  void _finishSending() {
500	    _isSending = false;
501	    if (isClosed) {
502	      return;
503	    }
504	    final current = state;
505	    if (current is ChatReady) {
506	      emit(current.copyWith(isSending: false));
507	    }
508	  }
509	
510	  void _applyStreamEvent(
511	    String userMessageId,
512	    String aiMessageId,
513	    ChatStreamEvent event,
514	  ) {
515	    if (isClosed) {
516	      return;
517	    }
518	    final current = state;
519	    if (current is! ChatReady) {
520	      return;
521	    }
522	    switch (event) {
523	      case ChatMessageCreatedEvent(userMessageId: final serverId):
524	        // spec-6-3 — Design Notes: "the persisted *user*-message id" is
525	        // now this story's first consumer, captured onto the matching
526	        // local user bubble by id so a later `retryMessage` call (on the
527	        // AI bubble this same send produces) has a non-null `serverId` to
528	        // key `chat-messages-retry` off of.
529	        emit(
530	          current.copyWith(
531	            messages: [
532	              for (final message in current.messages)
533	                if (message.id == userMessageId)
534	                  message.copyWith(serverId: serverId)
535	                else
536	                  message,
537	            ],
538	          ),
539	        );
540	      case ChatTokenEvent(delta: final delta):
541	        emit(
542	          current.copyWith(
543	            messages: [
544	              for (final message in current.messages)
545	                if (message.id == aiMessageId)
546	                  message.copyWith(content: message.content + delta)
547	                else
548	                  message,
549	            ],
550	          ),
551	        );
552	      case ChatDoneEvent():
553	        emit(
554	          current.copyWith(
555	            messages: [
556	              for (final message in current.messages)
557	                if (message.id == aiMessageId)
558	                  message.copyWith(status: ChatMessageStatus.complete)
559	                else
560	                  message,
561	            ],
562	          ),
563	        );
564	    }
565	  }
566	
567	  /// I/O matrix: "Mid-stream drop"/"In-band `error` event" — marks the one
568	  /// bubble `failed`, by id, leaving its already-streamed-in text exactly
569	  /// as-is (never cleared, Boundaries).
570	  void _markFailed(String aiMessageId) {
571	    if (isClosed) {
572	      return;
573	    }
574	    final current = state;
575	    if (current is! ChatReady) {
576	      return;
577	    }
578	    emit(
579	      current.copyWith(
580	        messages: [
581	          for (final message in current.messages)
582	            if (message.id == aiMessageId)
583	              message.copyWith(status: ChatMessageStatus.failed)
584	            else
585	              message,
586	        ],
587	      ),
588	    );
589	  }
590	
591	  String _nextLocalId() => 'local-${_localIdCounter++}';
592	
593	  /// spec-6-3 — [_connectivityWatcher]'s own listener: [isOnline] `true`
594	  /// means the device currently has connectivity. Always updates
595	  /// [_isOffline] (even outside [ChatReady] — see [_isOffline]'s own doc),
596	  /// but only *emits* when already [ChatReady] and the value actually
597	  /// changed, so an unrelated repeated emission of the same status (e.g.
598	  /// a plugin re-announcing "still online") never triggers a spurious
599	  /// rebuild.
600	  void _handleConnectivityChange(bool isOnline) {
601	    _isOffline = !isOnline;
602	    if (isClosed) {
603	      return;
604	    }
605	    final current = state;
606	    if (current is ChatReady && current.isOffline != _isOffline) {
607	      emit(current.copyWith(isOffline: _isOffline));
608	    }
609	  }
610	
611	  /// Review finding: "Cross-session stream leakage" — [switchSession]/
612	  /// [startNewSession] call this before touching anything else whenever
613	  /// they're about to make a *different* session active, so a response
614	  /// still streaming into the session being left behind can never go on
615	  /// to mutate the one that replaces it. Exactly [close]'s own cleanup
616	  /// below (cancel the subscription, resolve the stranded [sendMessage]
617	  /// caller, clear the re-entrancy guard), just without closing the cubit
618	  /// itself — a no-op when nothing is actually in flight.
619	  Future<void> _cancelInFlightSend() async {
620	    if (!_isSending) {
621	      return;
622	    }
623	    await _sendSubscription?.cancel();
624	    _sendSubscription = null;
625	    final completer = _sendCompleter;
626	    if (completer != null && !completer.isCompleted) {
627	      completer.complete();
628	    }
629	    _sendCompleter = null;
630	    _isSending = false;
631	  }
632	
633	  @override
634	  Future<void> close() {
635	    _connectivitySubscription?.cancel();
636	    _sendSubscription?.cancel();
637	    final completer = _sendCompleter;
638	    if (completer != null && !completer.isCompleted) {
639	      completer.complete();
640	    }
641	    _sendCompleter = null;
642	    return super.close();
643	  }
644	}
